mkdir -p /app/bin /app/out; cat > /app/bin/tally.py <<'EOF'
import sys, os, json, csv, io, re, unicodedata


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = unicodedata.normalize("NFC", str(s)).casefold()
    s = "".join(c if c.isalnum() else " " for c in s)
    return " ".join(s.split())


def read_batches(cvr):
    files = []
    for n in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, n)
        if os.path.isfile(p) and (n.endswith(".csv") or n.endswith(".jsonl")):
            files.append(p)
    out = []  # (batch, rev, status, records)
    for p in files:
        with open(p, encoding="utf-8", newline="") as f:
            text = f.read()
        lines = text.split("\n")
        recs = []
        if p.endswith(".jsonl"):
            meta = None
            for ln in lines:
                if not ln.strip():
                    continue
                o = json.loads(ln)
                if meta is None:
                    meta = o
                    continue
                rk = {}
                for m in o.get("marks", []):
                    r = int(m["rank"])
                    if "write_in" in m and m.get("write_in") is not None:
                        rk.setdefault(r, []).append(("w", m["write_in"]))
                    else:
                        rk.setdefault(r, []).append(("c", m["candidate"]))
                recs.append((o["contest"], rk))
            b, rev, st = meta["batch"], meta["revision"], meta["status"]
        else:
            meta = {}
            body = []
            for ln in lines:
                if ln.startswith("#"):
                    m = re.match(r"#\s*([^:]*?)\s*:\s*(.*?)\s*$", ln.rstrip("\r"))
                    if m:
                        meta[m.group(1).strip().lower()] = m.group(2)
                elif ln.strip():
                    body.append(ln)
            rd = csv.reader(io.StringIO("\n".join(body), newline=""))
            header = None
            for row in rd:
                if not row:
                    continue
                if header is None:
                    header = [h.strip() for h in row]
                    continue
                d = dict(zip(header, row))
                rk = {}
                for i, h in enumerate(header):
                    mm = re.fullmatch(r"rank(\d+)", h)
                    if not mm or i >= len(row):
                        continue
                    cell = row[i]
                    if cell.strip() == "":
                        continue
                    marks = []
                    for part in cell.split("|"):
                        if part.strip() == "":
                            continue
                        if part.startswith("WI:"):
                            marks.append(("w", part[3:]))
                        else:
                            marks.append(("c", part))
                    if marks:
                        rk[int(mm.group(1))] = marks
                recs.append((d["contest"].strip(), rk))
            b, rev, st = meta["batch"], meta["revision"], meta["status"]
        out.append((str(b), int(str(rev).strip()), str(st).strip().lower(), recs))
    best = {}
    for b, rev, st, recs in out:
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
    res = []
    for b in sorted(best):
        rev, st, recs = best[b]
        if st != "void":
            res.extend(recs)
    return res


def read_ballot(rk, contest, cmap, wmap, withdrawn):
    """Return list of rankings: ('s',), ('p',), ('c', id), ('o',)"""
    out = []
    seen = set()
    for r in range(1, contest["max_ranks"] + 1):
        marks = set()
        for kind, v in rk.get(r, []):
            if kind == "w":
                c = wmap.get(norm_text(v))
                if c is not None:
                    marks.add(c)
            else:
                marks.add(cmap.get(norm_id(v), norm_id(v)))
        if not marks:
            out.append(("s",))
            continue
        marks -= withdrawn
        if not marks:
            out.append(("p",))
            continue
        new = marks - seen
        seen |= marks
        if not new:
            out.append(("s",))
            continue
        marks = new
        if len(marks) == 1:
            out.append(("c", next(iter(marks))))
        else:
            out.append(("o",))
    return out


def count_for(ranks, cont):
    n = len(ranks)
    for i, r in enumerate(ranks):
        k = r[0]
        if k == "c":
            if r[1] in cont:
                return r[1]
        elif k == "o":
            return None
        elif k == "s":
            if i + 1 < n and ranks[i + 1][0] == "s":
                return None
    return None


def run_contest(contest, recs):
    cands = {}  # norm -> canonical
    withdrawn = set()
    active = []
    for c in contest["candidates"]:
        k = norm_id(c["id"])
        cands[k] = c["id"]
        if c.get("status") == "withdrawn":
            withdrawn.add(k)
        else:
            active.append(k)
    wmap = {}
    for w in contest.get("write_ins", []):
        k = norm_id(w["id"])
        cands[k] = w["id"]
        active.append(k)
        for t in [w["name"]] + list(w.get("aliases", [])):
            wmap[norm_text(t)] = k
    lot = [norm_id(x) for x in contest.get("lot_order", [])]
    lotpos = {c: i for i, c in enumerate(lot)}
    ballots = [read_ballot(rk, contest, cands, wmap, withdrawn) for rk in recs]
    total = len(ballots)
    cont = list(active)
    hist = []
    rounds = []
    winner = None
    rn = 0
    while True:
        rn += 1
        cs = set(cont)
        t = {c: 0 for c in cont}
        act = 0
        for b in ballots:
            c = count_for(b, cs)
            if c is not None:
                t[c] += 1
                act += 1
        hist.append(t)
        entry = {"round": rn, "tallies": {cands[c]: v for c, v in t.items()},
                 "exhausted": total - act, "eliminated": []}
        rounds.append(entry)
        if act == 0:
            break
        win = None
        for c in cont:
            if t[c] * 2 > act:
                win = c
        if win is None and len(cont) == 1:
            win = cont[0]
        if win is not None:
            winner = cands[win]
            break
        zeros = [c for c in cont if t[c] == 0]
        if zeros:
            el = zeros
        else:
            m = min(t.values())
            tied = [c for c in cont if t[c] == m]
            j = rn - 2
            while len(tied) > 1 and j >= 0:
                mm = min(hist[j][c] for c in tied)
                tied = [c for c in tied if hist[j][c] == mm]
                j -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lotpos.get(c, -1))]
            el = tied
        entry["eliminated"] = sorted(cands[c] for c in el)
        cont = [c for c in cont if c not in el]
    return {"contest": contest["id"], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    recs = read_batches(os.path.join(inp, "cvr"))
    by = {}
    for cid, rk in recs:
        by.setdefault(cid, []).append(rk)
    res = {"election": el["election"],
           "contests": [run_contest(c, by.get(c["id"], [])) for c in el["contests"]]}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
